local p=game.Players.LocalPlayer local g=p:FindFirstChild("PlayerGui") or game:GetService("CoreGui") if gethui then pcall(function() g=gethui() end) end for _,v in pairs(g:GetChildren()) do if v.Name=="A" then v:Destroy() end end
local sg=Instance.new("ScreenGui",g) sg.Name="A" sg.ResetOnSpawn=false
local bola=Instance.new("TextButton",sg) bola.Size=UDim2.new(0,60,0,60) bola.Position=UDim2.new(0.05,0,0.5,0) bola.Text="A" bola.BackgroundColor3=Color3.fromRGB(255,0,0) bola.TextColor3=Color3.new(1,1,1) bola.Font=Enum.Font.GothamBlack bola.TextSize=28 Instance.new("UICorner",bola).CornerRadius=UDim.new(1,0) bola.Active=true bola.Draggable=true
local m=Instance.new("Frame",sg) m.Size=UDim2.new(0,200,0,220) m.Position=UDim2.new(0.5,-100,0.5,-110) m.BackgroundColor3=Color3.fromRGB(18,18,18) m.Visible=true Instance.new("UICorner",m).CornerRadius=UDim.new(0,10)
local function btn(t,y,c) local b=Instance.new("TextButton",m) b.Size=UDim2.new(0.9,0,0,28) b.Position=UDim2.new(0.05,0,0,y) b.Text=t b.BackgroundColor3=c b.TextColor3=Color3.new(1,1,1) b.Font=Enum.Font.GothamBold b.TextSize=11 Instance.new("UICorner",b).CornerRadius=UDim.new(0,6) return b end
local b1=btn("Speed 500",10,Color3.fromRGB(0,170,0)) local b2=btn("Guardar Base",42,Color3.fromRGB(255,165,0)) local b3=btn("TP BASE SIN LAG",74,Color3.fromRGB(0,200,100)) local b4=btn("AUTO ROBAR OFF",106,Color3.fromRGB(150,0,150)) local b5=btn("TP RAPIDO",138,Color3.fromRGB(0,120,255)) local b6=btn("Cerrar",170,Color3.fromRGB(80,0,0))
bola.MouseButton1Click:Connect(function() m.Visible=not m.Visible end)
b1.MouseButton1Click:Connect(function() p.Character:FindFirstChildOfClass("Humanoid").WalkSpeed=500 end)
local base=nil b2.MouseButton1Click:Connect(function() base=p.Character.HumanoidRootPart.CFrame b2.Text="Guardada!" wait(1) b2.Text="Guardar Base" end)
local function tpNoLag(cf) local hrp=p.Character.HumanoidRootPart hrp.Velocity=Vector3.new(0,0,0) hrp.CFrame=cf+Vector3.new(0,5,0) wait(0.05) hrp.Velocity=Vector3.new(0,0,0) end
b3.MouseButton1Click:Connect(function() if base then tpNoLag(base) end end)
b5.MouseButton1Click:Connect(function() if base then for i=1,3 do p.Character.HumanoidRootPart.CFrame=base+Vector3.new(0,5,0) wait(0.1) end end end)
b6.MouseButton1Click:Connect(function() sg:Destroy() end)
local auto=false b4.MouseButton1Click:Connect(function() auto=not auto b4.Text="AUTO ROBAR "..(auto and "ON" or "OFF") end) spawn(function() while wait(0.2) do if auto then pcall(function() for _,v in pairs(workspace:GetDescendants()) do if v:IsA("ProximityPrompt") and (p.Character.HumanoidRootPart.Position-v.Parent.Position).Magnitude<15 then fireproximityprompt(v) end end end) end end end)